"""Write ui/js/demo-data.js from flex_scratchpad.flex.demo so the in-browser mock shows the
same demo project as the Python side. Run after editing demo.py:  python tools/gen_demo_js.py"""
import json
import pathlib
import sys

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1]))
from flex_scratchpad.flex import demo  # noqa: E402

be = demo.DemoBackend()
data = {"entries": demo.ENTRIES, "texts": be.texts}
out = pathlib.Path(__file__).resolve().parents[1] / "flex_scratchpad" / "ui" / "js" / "demo-data.js"
out.write_text(
    "/* demo-data.js — GENERATED by tools/gen_demo_js.py from flex_scratchpad/flex/demo.py. Do not edit. */\n"
    "(function(){ 'use strict'; const FS = (window.FS = window.FS || {});\n"
    "  const DATA = " + json.dumps(data, ensure_ascii=False) + ";\n"
    "  FS.demoData = () => JSON.parse(JSON.stringify(DATA));\n})();\n",
    encoding="utf-8",
)
print("wrote", out, out.stat().st_size, "bytes")
